          programId: 'radio-1',
          songId: null,
          assetId: 'ad,1', // comma in assetId to test escaping
          state: 'started',
          at: new Date('2026-11-15T10:05:00.000Z'),
          createdAt: new Date('2026-11-15T10:05:00.000Z'),
