        {
          id: 5,
          programId: 'radio-1',
          songId: 11,
          assetId: null,
          state: 'ended',
          at: new Date('2026-11-15T10:06:00.000Z'),
          createdAt: new Date('2026-11-15T10:06:00.000Z'),
