private async recordWithRetry(event: AsRunTrackEvent): Promise<void> {
  for (let attempt = 0; ; attempt += 1) {
    try {
      await this.handleTrackEvent(event);
      return;
    } catch (error) {
      const delay = AS_RUN_RECORD_BACKOFF_MS[attempt];
      if (delay === undefined) {
        this.logger.warn(
